#include "caller_probe.hpp"
#include <cstdio>
#include <sstream>

using caller_probe::Interval;
using caller_probe::partition;
static void require(bool ok) {
    if (!ok) throw std::runtime_error("accounting self-check failed");
}

int main() {
    const std::vector<Interval> steps{{10, 90}};
    const std::vector<Interval> primitives{{20, 70}};
    const std::vector<Interval> dispatches{{30, 60}};
    const std::vector<Interval> observers{{12, 16}, {14, 18}, {22, 25}, {31, 35}, {92, 94}};
    const auto t = partition(0, 100, steps, primitives, dispatches, observers);
    require(t.dispatch == 30 && t.backend == 17 && t.model == 24 && t.harness == 18 && t.observer == 11);
    const auto empty = partition(0, 100, {}, {}, {}, {});
    require(empty.harness == 100);
    const auto adjacent = partition(0, 100, {{0, 50}, {50, 100}}, {{10, 40}, {60, 90}},
                                    {{20, 30}, {70, 80}}, {});
    require(adjacent.dispatch == 20 && adjacent.backend == 40 && adjacent.model == 40);
    int rejected = 0;
    auto reject = [&](auto work) {
        try { work(); }
        catch (const std::runtime_error&) { ++rejected; return; }
        throw std::runtime_error("malformed interval accepted");
    };
    reject([&] { partition(0, 100, {{10, 90}, {20, 40}}, {}, {}, {}); });
    reject([&] { partition(0, 100, steps, {{20, 70}, {40, 80}}, {}, {}); });
    reject([&] { partition(0, 100, steps, primitives, {{30, 60}, {40, 65}}, {}); });
    reject([&] { partition(0, 100, steps, {{20, 70}, {20, 70}}, {}, {}); });
    reject([&] { partition(0, 100, steps, {{20, 70}}, {{30, 60}, {30, 60}}, {}); });
    reject([&] { partition(0, 100, {{10, 40}, {50, 90}}, {{20, 70}}, {}, {}); });
    reject([&] { partition(0, 100, steps, {{20, 40}, {50, 70}}, {{30, 60}}, {}); });
    reject([&] { partition(0, 100, steps, primitives, {{60, 30}}, {}); });
    reject([&] { partition(0, 100, steps, primitives, dispatches, {{-1, 2}}); });
    reject([&] { partition(0, 100, steps, primitives, dispatches, {{99, 101}}); });
    reject([&] { partition(0, 100, steps, primitives, dispatches, {{40, 30}}); });
    reject([&] { partition(0, 100, {}, primitives, dispatches, {}); });
    reject([&] { partition(0, 100, steps, {}, dispatches, {}); });
    reject([&] { partition(100, 0, {}, {}, {}, {}); });
    require(rejected == 14);

    caller_probe::Trace trace(2);
    trace.start();
    caller_probe::region(caller_probe::LayerInput);
    caller_probe::region(caller_probe::SwiGLU);
    caller_probe::region(caller_probe::TokenReturn);
    trace.finish();
    require(trace.overflow);
    std::ostringstream out;
    trace.dump(out);
    require(out.str().find("\"overflow\":true") != std::string::npos);
    std::printf("accounting: 3 exact partitions, 14 malformed interval rejections, trace overflow check\n");
}

