from pathlib import Path
import hashlib
import json
import statistics
from validate_trace import validate

root = Path(__file__).resolve().parent
state = json.loads((root/'timing/results.json').read_text())
assert state['status'] == 'pass' and len(state['rows']) == 12
manifest = json.loads((root/'manifest.json').read_text())
for name, expected in manifest.items():
    assert hashlib.sha256((root/name).read_bytes()).hexdigest() == expected['sha256'], name
records = []
for row in state['rows']:
    assert row['status'] == 'pass' and row['returncode'] == 0
    doc = json.loads((root/'timing'/(row['name']+'.stdout')).read_text())
    raw = (root/'timing'/(row['name']+'.f32')).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == state['plan']['historical_vector_sha256']
    assert (root/'timing'/(row['name']+'.f32.warmup')).read_bytes() == raw
    if row['arm'] == 'attributed':
        result = validate(doc)
        saved = json.loads((root/'timing'/(row['name']+'.attribution.json')).read_text())
        assert saved == result
        records.append(dict(pair=row['pair'], **result))

measured = [r for r in records if r['pair'] >= 0]
assert len(measured) == 3
def stats(xs):
    return dict(samples=xs, mean=statistics.mean(xs), median=statistics.median(xs),
                minimum=min(xs), maximum=max(xs))

summary = {}
for field in ['categories_ns','model_regions_ns','backend_parts_ns','outer_fringe_ns']:
    summary[field.replace('_ns','_ms_per_token')] = {
        k:stats([r[field][k]/32/1e6 for r in measured]) for k in measured[0][field]}

phase = {}
for metric in ['pp_ms','tg_ms']:
    arms = {arm:[r[metric] for r in state['rows'] if r['pair'] >= 0 and r['arm'] == arm]
            for arm in ['plain','spans','attributed']}
    phase[metric] = {arm:stats(v) for arm,v in arms.items()}
    for numerator,denominator in [('spans','plain'),('attributed','plain'),('attributed','spans')]:
        key=numerator+'_vs_'+denominator
        phase[metric][key] = {
            'mean_elapsed_percent':100*(statistics.mean(arms[numerator])/statistics.mean(arms[denominator])-1),
            'paired_elapsed_percent':[100*(a/b-1) for a,b in zip(arms[numerator],arms[denominator])],
            'paired_ms_per_token':[(a-b)/(32 if metric == 'tg_ms' else 215)
                                   for a,b in zip(arms[numerator],arms[denominator])]}

result = dict(status='pass', checked_manifest_files=len(manifest),
              invocations=12, finite_exact_final_vectors=24, attributed_traces=4,
              measured_attributed_traces=3, source_unchanged=True,
              records=records, summary=summary, phase_comparison=phase,
              calibration=json.loads((root/'calibration-summary.json').read_text()),
              limits='Current 8B six-thread 215+32 workload only. Diagnostic observed intervals and observer comparisons, not recoverable production costs or external HF/mx acceptance. No timing samples removed; pair -1 is the prospectively discarded warmup.')
(root/'analysis.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({'summary':summary,'phase_comparison':phase},indent=2))

