#include "caller_probe.hpp"
#include <iostream>
#include <array>

int main() {
    std::array<int64_t, 10000> pairs{};
    caller_probe::Trace trace;
    for (auto& delta : pairs) {
        auto before = caller_probe::stamp();
        auto after = caller_probe::stamp();
        delta = after - before;
    }
    auto before = caller_probe::stamp();
    trace.start();
    for (int i = 0; i < 10000; ++i)
        caller_probe::region(caller_probe::SwiGLU);
    trace.finish();
    auto after = caller_probe::stamp();
    std::cout << "{\"iterations\":10000,\"marker_outer_ns\":" << after-before
              << ",\"clock_pair_ns\":[";
    for (size_t i = 0; i < pairs.size(); ++i) {
        if (i) std::cout << ',';
        std::cout << pairs[i];
    }
    std::cout << "],\"caller\":";
    trace.dump(std::cout);
    std::cout << "}\n";
}

