#pragma once
#include <algorithm>
#include <array>
#include <chrono>
#include <cstdint>
#include <ostream>
#include <stdexcept>
#include <vector>

namespace caller_probe {
inline int64_t stamp() noexcept {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
}
enum Kind { StepEnter, StepExit, PrimitiveEnter, PrimitiveExit,
            ParallelEnter, ParallelExit, RegionMark, LegacyObserver };
enum Region { CacheEmbedding, LayerInput, HeadMathCache, AttentionOutput,
              AttentionResidual, SwiGLU, DownPrepare, DownResidual,
              FinalPrepare, TokenReturn };
enum Primitive { Matmul, Group, Attention };
struct Event { int kind = 0, tag = 0; int64_t begin = 0, end = 0; };
class Trace;
inline thread_local Trace* active = nullptr;

class Trace {
    std::vector<Event> events_;
    size_t used_ = 0;
    int64_t start_ = 0, end_ = 0;
public:
    bool overflow = false, invalid = false;
    int primitive_depth = 0;
    explicit Trace(size_t capacity = 65536) : events_(capacity) {}
    Trace(const Trace&) = delete;
    Trace& operator=(const Trace&) = delete;
    ~Trace() { if (active == this) active = nullptr; }
    void start() {
        if (active) throw std::runtime_error("caller trace already active");
        used_ = 0;
        end_ = 0;
        overflow = invalid = false;
        primitive_depth = 0;
        active = this;
        start_ = stamp();
    }
    void finish() {
        if (active != this) throw std::runtime_error("caller trace not active");
        end_ = stamp();
        active = nullptr;
        if (primitive_depth) invalid = true;
    }
    void event(int kind, int tag, int64_t begin = 0) noexcept {
        if (active != this) { invalid = true; return; }
        if (!begin) begin = stamp();
        if (used_ == events_.size()) { overflow = true; return; }
        auto& e = events_[used_++];
        e.kind = kind;
        e.tag = tag;
        e.begin = begin;
        e.end = stamp();
    }
    void dump(std::ostream& out) const {
        if (active == this || !end_) throw std::runtime_error("caller trace unfinished");
        out << "{\"start_ns\":" << start_ << ",\"end_ns\":" << end_
            << ",\"capacity\":" << events_.size()
            << ",\"overflow\":" << (overflow ? "true" : "false")
            << ",\"invalid\":" << (invalid ? "true" : "false") << ",\"events\":[";
        for (size_t i = 0; i < used_; ++i) {
            if (i) out << ',';
            const auto& e = events_[i];
            out << '[' << e.kind << ',' << e.tag << ',' << e.begin << ',' << e.end << ']';
        }
        out << "]}";
    }
};

class Scope {
    Trace* trace_ = active;
    int kind_, tag_;
    bool emit_ = false;
public:
    Scope(int kind, int tag = 0) noexcept : kind_(kind), tag_(tag) {
        if (!trace_) return;
        emit_ = kind != PrimitiveEnter || trace_->primitive_depth++ == 0;
        if (emit_) trace_->event(kind_, tag_);
    }
    Scope(const Scope&) = delete;
    Scope& operator=(const Scope&) = delete;
    ~Scope() noexcept {
        if (!trace_) return;
        if (emit_) trace_->event(kind_ + 1, tag_);
        if (kind_ == PrimitiveEnter) --trace_->primitive_depth;
    }
};
inline void region(int tag) noexcept {
    if (active) active->event(RegionMark, tag);
}
class Observer {
    Trace* trace_ = active;
    int64_t begin_ = trace_ ? stamp() : 0;
public:
    Observer() = default;
    Observer(const Observer&) = delete;
    Observer& operator=(const Observer&) = delete;
    ~Observer() noexcept { if (trace_) trace_->event(LegacyObserver, 0, begin_); }
};

struct Interval { int64_t begin, end; };
struct Totals {
    int64_t dispatch = 0, backend = 0, model = 0, harness = 0, observer = 0;
};

inline Totals partition(int64_t begin, int64_t end,
                        const std::vector<Interval>& steps,
                        const std::vector<Interval>& primitives,
                        const std::vector<Interval>& dispatches,
                        const std::vector<Interval>& observers) {
    if (begin >= end) throw std::runtime_error("invalid phase");
    auto validate = [&](const std::vector<Interval>& spans, bool disjoint) {
        for (size_t i = 0; i < spans.size(); ++i) {
            const auto& s = spans[i];
            if (s.begin < begin || s.end > end || s.begin > s.end ||
                (disjoint && i && (s.begin < spans[i - 1].end ||
                 (s.begin == spans[i - 1].begin && s.end == spans[i - 1].end))))
                throw std::runtime_error("invalid or overlapping interval");
        }
    };
    validate(steps, true);
    validate(primitives, true);
    validate(dispatches, true);
    validate(observers, false);
    auto contained = [](const std::vector<Interval>& children, const std::vector<Interval>& parents) {
        size_t p = 0;
        for (const auto& c : children) {
            while (p < parents.size() && parents[p].end < c.end) ++p;
            if (p == parents.size() || c.begin < parents[p].begin || c.end > parents[p].end)
                throw std::runtime_error("interval crosses parent");
        }
    };
    contained(primitives, steps);
    contained(dispatches, primitives);
    struct Edge { int64_t t; int kind, delta; };
    std::vector<Edge> edges;
    for (int k = 0; k < 4; ++k) {
        const auto& spans = k == 0 ? steps : k == 1 ? primitives : k == 2 ? dispatches : observers;
        for (const auto& s : spans) if (s.begin != s.end) {
            edges.push_back({s.begin, k, 1});
            edges.push_back({s.end, k, -1});
        }
    }
    edges.push_back({begin, 0, 0});
    edges.push_back({end, 0, 0});
    std::sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) { return a.t < b.t; });
    std::array<int, 4> depth{};
    int64_t previous = begin;
    Totals result;
    for (size_t i = 0; i < edges.size();) {
        const int64_t t = edges[i].t, dt = t - previous;
        if (depth[2]) result.dispatch += dt;
        else if (depth[3]) result.observer += dt;
        else if (depth[1]) result.backend += dt;
        else if (depth[0]) result.model += dt;
        else result.harness += dt;
        do { depth[edges[i].kind] += edges[i].delta; ++i; } while (i < edges.size() && edges[i].t == t);
        if (depth[0] < 0 || depth[0] > 1 || depth[1] < 0 || depth[1] > 1 ||
            depth[2] < 0 || depth[2] > 1 || depth[3] < 0 ||
            (depth[2] && !depth[1]) || (depth[1] && !depth[0]))
            throw std::runtime_error("invalid nesting");
        previous = t;
    }
    if (result.dispatch + result.backend + result.model + result.harness + result.observer != end - begin)
        throw std::runtime_error("partition does not sum");
    return result;
}
}

