#include <chrono>
#include <cstdint>
#include <iostream>
volatile std::uint64_t observed = 0;
__declspec(noinline) std::uint64_t sample_integer_mix(std::uint64_t value) {
    for (unsigned i=0; i<4000000; ++i) {
        value ^= value >> 13;
        value *= 0x9e3779b185ebca87ULL;
        value += i;
    }
    return value;
}
__declspec(noinline) std::uint64_t sample_rotate_mix(std::uint64_t value) {
    for (unsigned i=0; i<4000000; ++i) {
        value = (value << 7) | (value >> 57);
        value ^= 0xd1b54a32d192ed03ULL + i;
        value *= 0x94d049bb133111ebULL;
    }
    return value;
}
int main() {
    auto until = std::chrono::steady_clock::now() + std::chrono::seconds(14);
    std::uint64_t value=7;
    do {
        value=sample_integer_mix(value);
        value=sample_rotate_mix(value);
        observed=value;
    } while(std::chrono::steady_clock::now()<until);
    std::cout << value << '\n';
}

